package com.chotomua.backend.modules.marketing;
import com.chotomua.backend.modules.marketing.dto.*; import com.chotomua.backend.modules.order.*; import jakarta.validation.Valid; import java.util.*; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/reviews") public class ReviewController { private final ReviewRepository reviews; private final OrderItemRepository items; private final OrderRepository orders; public ReviewController(ReviewRepository r,OrderItemRepository i,OrderRepository o){reviews=r;items=i;orders=o;}
 @PostMapping public ResponseEntity<ReviewResponse> create(Authentication a,@Valid @RequestBody ReviewRequest q){UUID u=UUID.fromString((String)a.getPrincipal()); OrderItem item=items.findById(q.orderItemId()).orElseThrow(); Order order=orders.findByIdAndUserId(item.getOrderId(),u).orElseThrow(); if(!"delivered".equals(order.getStatus()))throw new IllegalStateException("Chỉ đánh giá đơn đã giao"); if(reviews.findByOrderItemId(item.getId()).isPresent())throw new IllegalStateException("Bạn đã đánh giá sản phẩm này"); return ResponseEntity.status(HttpStatus.CREATED).body(ReviewResponse.from(reviews.save(new Review(u,item.getId(),q.rating(),q.comment())))); }
}
